query:
mutation SignUp($email: String!, $password: String!, $captchaToken: String, $locale: String, $verifyEmailRedirectPath: String, $affiliatePartnerName: String) {
  signUp(
    email: $email
    password: $password
    captchaToken: $captchaToken
    locale: $locale
    verifyEmailRedirectPath: $verifyEmailRedirectPath
    affiliatePartnerName: $affiliatePartnerName
  ) {
    availableWorkspaces {
      ...AvailableWorkspacesFragment
      __typename
    }
    tokens {
      ...AuthTokenPairFragment
      __typename
    }
    __typename
  }
}

fragment AvailableWorkspaceFragment on AvailableWorkspace {
  id
  displayName
  loginToken
  inviteHash
  personalInviteToken
  workspaceUrls {
    subdomainUrl
    customUrl
    __typename
  }
  logo
  sso {
    type
    id
    issuer
    name
    status
    __typename
  }
  __typename
}

fragment AuthTokenFragment on AuthToken {
  token
  expiresAt
  __typename
}

fragment AvailableWorkspacesFragment on AvailableWorkspaces {
  availableWorkspacesForSignIn {
    ...AvailableWorkspaceFragment
    __typename
  }
  availableWorkspacesForSignUp {
    ...AvailableWorkspaceFragment
    __typename
  }
  __typename
}

fragment AuthTokenPairFragment on AuthTokenPair {
  accessOrWorkspaceAgnosticToken {
    ...AuthTokenFragment
    __typename
  }
  refreshToken {
    ...AuthTokenFragment
    __typename
  }
  __typename
}
